 boolclass_exists
 stringclass
 boolautoload&true;



 Cette fonction vérifie si une classe donnée a été définie.

&reftitle.returnvalues;


 Retourne &true; si class est une classe définie,
 &false; sinon.

&reftitle.changelog;





    &Version;
    &Description;





    8.5.0

     Un trait manquant lance désormais une exception
     Error au lieu de provoquer une erreur
     fatale E_ERROR.

  &reftitle.examples;



    Exemple avec class_exists


<?php
// Vérifie que la classe existe avant de l'utiliser
if (class_exists('MyClass')) {
    $myclass = new MyClass();
}

?>




    Exemple avec le paramètre autoload


<?php
spl_autoload_register(function ($class_name) {
    include $class_name . '.php';

    // Vérifie si l'include a déclaré la classe
    if (!class_exists($class_name, false)) {
        throw new LogicException("Unable to load class: $class_name");
    }
});

if (class_exists(MyClass::class)) {
    $myclass = new MyClass();
}

?>
